 "content": "from collections import Counter, deque

def components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); q.append(p)
            out.append((color,cells))
    return out

def exact_l(cells):
    if len(cells)<3: return None
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    for (r,c),d1,d2 in [((r0,c0),(0,1),(1,0)),((r0,c1),(0,-1),(1,0)),((r1,c0),(0,1),(-1,0)),((r1,c1),(0,-1),(-1,0))]:
        a={(r+k*d1[0],c+k*d1[1]) for k in range((r1-r0 if d1[0] else c1-c0)+1)}
        b={(r+k*d2[0],c+k*d2[1]) for k in range((r1-r0 if d2[0] else c1-c0)+1)}
        if cells==a|b: return (r,c),d1,d2
    return None

def transform(grid):
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=components(grid,bg)
    ls=[(color,cells,exact_l(cells)) for color,cells in comps if exact_l(cells)]
    if len(ls)<2: return [row[:] for row in grid]
    marker=max(ls,key=lambda x:len(x[1])); mc,ms,(corner,d1,d2)=marker
    r,c=corner
    # Pair the large L indicator with the smaller L situated diagonally opposite its arms.
    opp=[]
    for color,cells,ori in ls:
        if cells==ms: continue
        cy=sum(y for y,x in cells)/len(cells); cx=sum(x for y,x in cells)/len(cells)
        sy=-d2[0] if d2[0] else -d1[0]
        sx=-d1[1] if d1[1] else -d2[1]
        if (cy-r)*sy>0 and (cx-c)*sx>0:
            opp.append((len(cells),cells))
    if not opp: return [row[:] for row in grid]
    target=min(opp,key=lambda z:z[0])[1]
    out=[row[:] for row in grid]
    for y,x in target: out[y][x]=mc
    return out
